    li a0,221
    c.j .Lcj_ok
    j .Lreturn
.Lcj_ok:
    # Preserve caller RA on stack; compressed JAL must set PC+2.
    li a0,222
    c.jal .Lcjal_function
    j .Lcjal_after
.Lcjal_function:
    c.jr ra
.Lcjal_after:
    li a0,223
    la t0,.Lcjalr_function
    c.jalr t0
    j .Lcjalr_after
.Lcjalr_function:
    c.jr ra
.Lcjalr_after:
.option norvc
    # CSR instructions: zero-mask reads of read-only counters, and CSRRW
    # against mepc (restore before returning). Unsupported CSRs are not
    # assumed to implement a full privileged-mode ISA.
    csrrs t0,0xc00,zero
    csrrc t1,0xc00,zero
    csrrsi t2,0xc00,0
    csrrci a2,0xc00,0
    csrrs t1,0x341,zero
    li t0,0x100
    csrrw t2,0x341,t0
    csrrs t2,0x341,zero
    li a0,224
    li a5,0x100
    bne t2,a5,.Lrestore_mepc
    li t0,0x10
    csrrwi t2,0x341,16
    csrrs t2,0x341,zero
    li a0,225
    li a5,0x10
    bne t2,a5,.Lrestore_mepc
    # CSR-immediate edge cases use architectural zimm, never x16..x31 GPRs.
    csrrwi t2,0x341,30
    csrrs t2,0x341,zero
    li a0,226
    li a5,30
    bne t2,a5,.Lrestore_mepc
    csrrci t2,0x341,16
    csrrs t2,0x341,zero
    li a0,227
    li a5,14
    bne t2,a5,.Lrestore_mepc
    csrrsi t2,0x341,16
    csrrs t2,0x341,zero
    li a0,228
    li a5,30
    bne t2,a5,.Lrestore_mepc
    csrrsi t2,0x341,0
    csrrs t2,0x341,zero
    li a0,229
    li a5,30
    bne t2,a5,.Lrestore_mepc
    csrrci t2,0x341,0
    csrrs t2,0x341,zero
    li a0,230
    li a5,30
    bne t2,a5,.Lrestore_mepc
    li a0,0
.Lrestore_mepc:
    csrrw zero,0x341,t1
.Lreturn:
    lw ra,60(sp)
    lw s0,56(sp)
    lw s1,52(sp)
    addi sp,sp,64
    ret
.option pop
